Index: packages/demo/src/components/CustomFooterContent.vue
===================================================================
--- packages/demo/src/components/CustomFooterContent.vue	
+++ packages/demo/src/components/CustomFooterContent.vue	
@@ -1,26 +1,57 @@
 <template>
   <div class="custom-footer-content">
     <p>{{ message }}</p>
-    <p>Approve/Deny buttons are rendered in the footer, not in the body.</p>
+    <p>Approve/Deny buttons are rendered in the dialog footer via the named slot.</p>
+    <template slot="footer">
+      <button
+        class="vdl-dialog__btn"
+        @click="handleDeny"
+      >
+        Deny
+      </button>
+      <button
+        class="vdl-dialog__btn vdl-dialog__btn--primary"
+        @click="handleApprove"
+      >
+        Approve
+      </button>
+    </template>
   </div>
 </template>

 <script>
 export default {
   name: 'CustomFooterContent',

   props: {
     message: {
       type: String,
       default: '',
     },
+    dialogResolve: {
+      type: Function,
+      default: () => {},
+    },
+    dialogReject: {
+      type: Function,
+      default: () => {},
+    },
   },
+
+  methods: {
+    handleApprove() {
+      this.dialogResolve({ approved: true });
+    },
+    handleDeny() {
+      this.dialogReject('user denied');
+    },
+  },
 };
 </script>

 <style scoped>
 .custom-footer-content {
   font-size: 14px;
   line-height: 1.6;
 }
 </style>

Index: packages/demo/src/components/DialogDemo.vue
===================================================================
--- packages/demo/src/components/DialogDemo.vue	
+++ packages/demo/src/components/DialogDemo.vue	
@@ -1,250 +1,255 @@
 <template>
   <div class="demo-section">
     <h2>Modal Dialogs</h2>
     <div class="demo-buttons">
       <button @click="openBasicDialog">
         Basic Dialog
       </button>
       <button @click="openComponentDialog">
         Dialog with Component
       </button>
       <button @click="openStackedDialog">
         Stacked Dialog (nested)
       </button>
       <button @click="openCustomFooterDialog">
         Custom Footer
       </button>
+      <button @click="openStandardButtonsDialog">
+        Standard Buttons (bitmask)
+      </button>
       <button @click="openSizedDialog('60vw', '50vh')">
         Custom Size (60vw x 50vh)
       </button>
       <button @click="openSizedDialog('120vw', '120vh')">
         Custom Size (120vw x 120vh)
       </button>
       <button @click="openNonClosableDialog">
         No Close on Outside Click
       </button>
     </div>
     <div v-if="result" class="demo-result">
       <strong>Result:</strong> {{ result }}
     </div>
     <div v-if="error" class="demo-error">
       <strong>Error:</strong> {{ error }}
       <span class="close-button" @click="clearStatus">x</span>
     </div>
   </div>
 </template>

 <script>
 import SampleDialogContent from "./SampleDialogContent.vue";
 import StackedDemoContent from "./StackedDemoContent.vue";
 import CustomFooterContent from "./CustomFooterContent.vue";
+import { FOOTER_BUTTONS } from "vue2-dlg-lib";

 export default {
   name: "DialogDemo",

   data() {
     return {
       result: null,
       error: null,
     };
   },

   methods: {
     clearStatus() {
       this.result = null;
       this.error = null;
     },

     openBasicDialog() {
       this.clearStatus();
       this.$dialog
         .open({
           title: "Basic Dialog",
           width: "400px",
           height: "250px",
         })
         .then((data) => {
           this.result = JSON.stringify(data);
         })
         .catch((reason) => {
           this.error = "Rejected: " + reason;
         });
     },

     openComponentDialog() {
       this.clearStatus();
       this.$dialog
         .open({
           title: "Component Dialog",
           contentComponent: SampleDialogContent,
           contentProps: {
             message: "Hello from component!",
             customValue: "dynamic value",
           },
           width: "500px",
           height: "300px",
         })
         .then((data) => {
           this.result = JSON.stringify(data);
         })
         .catch((reason) => {
           this.error = "Rejected: " + reason;
         });
     },

     openStackedDialog() {
       this.clearStatus();
       this.$dialog
         .open({
           title: "Parent Dialog",
           contentComponent: StackedDemoContent,
           width: "480px",
           height: "280px",
         })
         .then((data) => {
           this.result = "Parent dialog resolved: " + JSON.stringify(data);
         })
         .catch((reason) => {
           this.error = "Parent dialog rejected: " + reason;
         });
     },

     openCustomFooterDialog() {
       this.clearStatus();

       this.$dialog
         .open({
           title: "Custom Footer Dialog",
           contentComponent: CustomFooterContent,
           contentProps: {
             message:
-              "This dialog has a custom footer with Approve/Deny buttons.",
+              "This dialog has a custom footer with Approve/Deny buttons defined by the child component's named slot.",
           },
           width: "480px",
           height: "320px",
-          footer: (h, { resolve, reject }) => [
-            h(
-              "button",
-              {
-                class: "vdl-dialog__btn",
-                on: { click: () => reject("user denied") },
-              },
-              "Deny"
-            ),
-            h(
-              "button",
-              {
-                class: "vdl-dialog__btn vdl-dialog__btn--primary",
-                on: { click: () => resolve({ approved: true }) },
-              },
-              "Approve"
-            ),
-          ],
         })
         .then((data) => {
           this.result = JSON.stringify(data);
         })
         .catch((reason) => {
           this.error = "Rejected: " + reason;
         });
     },

+    openStandardButtonsDialog() {
+      this.clearStatus();
+
+      this.$dialog
+        .open({
+          title: "Standard Buttons Dialog",
+          footerButtons:
+            FOOTER_BUTTONS.OK | FOOTER_BUTTONS.YES | FOOTER_BUTTONS.NO | FOOTER_BUTTONS.CLOSE | FOOTER_BUTTONS.CANCEL,
+          width: "480px",
+          height: "320px",
+        })
+        .then((data) => {
+          this.result = "Resolved: " + data;
+        })
+        .catch((reason) => {
+          this.error = "Rejected: " + reason;
+        });
+    },
+
     openSizedDialog(width, height) {
       this.clearStatus();
       this.$dialog
         .open({
           title: "Custom Size Dialog",
           width,
           height,
         })
         .then((data) => {
           this.result = JSON.stringify(data);
         })
         .catch((reason) => {
           this.error = "Rejected: " + reason;
         });
     },

     openNonClosableDialog() {
       this.clearStatus();
       this.$dialog
         .open({
           title: "No Outside Click Close",
           closeOnClickOutside: false,
           width: "400px",
           height: "250px",
         })
         .then((data) => {
           this.result = JSON.stringify(data);
         })
         .catch((reason) => {
           this.error = "Rejected: " + reason;
         });
     },
   },
 };
 </script>

 <style scoped>
 .demo-section {
   background: #fff;
   border-radius: 8px;
   padding: 20px;
   box-shadow: 0 1px 4px rgba(0, 0, 0, 0.08);
 }

 h2 {
   font-size: 20px;
   margin-bottom: 16px;
 }

 .demo-buttons {
   display: flex;
   flex-wrap: wrap;
   gap: 10px;
 }

 .demo-buttons button {
   padding: 8px 16px;
   border: 1px solid #d9d9d9;
   border-radius: 4px;
   background: #fff;
   cursor: pointer;
   font-size: 14px;
   transition: background 0.15s, border-color 0.15s;
 }

 .demo-buttons button:hover {
   background: #e6f7ff;
   border-color: #1890ff;
 }

 .demo-result {
   margin-top: 16px;
   padding: 10px 14px;
   background: #f6ffed;
   border: 1px solid #b7eb8f;
   border-radius: 4px;
   font-size: 13px;
   word-break: break-all;
 }

 .demo-error {
   margin-top: 16px;
   padding: 10px 14px;
   background: #fff2f0;
   border: 1px solid #ffccc7;
   border-radius: 4px;
   font-size: 13px;
   word-break: break-all;
 }

 .close-button {
   /* position: absolute;
   top: 0;
   right: 15px; */
   float: right;
   display: block;
   cursor: pointer;
 }
