extractFooterVnodes(root) {
  const result = [];
  if (!root || !root.children) return result;
  for (const child of root.children) {
    if (child.data && child.data.slot === 'footer') {
      const nodes = child.tag === 'template' && child.children ? child.children : [child];
      for (const node of nodes) {
        if (node.data) {
          delete node.data.slot;
          if (node.data.attrs) {
            delete node.data.attrs.slot;
          }
        }
        if (node.elm && node.elm.parentNode) {
          node.elm.parentNode.removeChild(node.elm);
        }
      }
      result.push(...nodes);
    }
  }
  return result;
},

reject(reason) {
  this.$emit('reject', reason);
},

resolve(data) {
  this.$emit('resolve', data);
},

toggleMaximize() {
  if (!this.isMaximized) {
    const rect = this.$refs.dialog.getBoundingClientRect();
    this.currentLeft = rect.left;
    this.currentTop = rect.top;
    this.currentWidth = rect.width;
    this.currentHeight = rect.height;
  }
  this.isMaximized = !this.isMaximized;
},

adjustPosition() {
  const dialog = this.$refs.dialog;
  if (!dialog || this.isMaximized) return;

  const rect = dialog.getBoundingClientRect();
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const MARGIN = 10;

  if (rect.top >= 0 && rect.left >= 0 && rect.bottom <= vh && rect.right <= vw) {
    return;
  }

  this.currentLeft = Math.max(MARGIN, Math.min(vw - rect.width - MARGIN, rect.left));
  this.currentTop = Math.max(MARGIN, Math.min(vh - rect.height - MARGIN, rect.top));
},

startDrag(e) {
  if (!this.draggable || this.isMaximized || e.target.closest('.vdl-dialog__btn')) {
    return;
  }
  this.isDragging = true;
  this.dragStartX = e.clientX;

